 82	export function scriptToHunks(
 83	  oldLines: string[],
 84	  newLines: string[],
 85	  script: EditOp[],
 86	  contextLines = 3,
 87	): DiffHunk[] {
 88	  const steps = buildSteps(oldLines, newLines, script);
 89	  const changed = steps.flatMap((step, index) => step.op === "keep" ? [] : [index]);
 90	  if (changed.length === 0) return [];
 91	
 92	  const ranges: Array<[number, number]> = [];
 93	  let first = changed[0]!;
 94	  let last = first;
 95	  for (const index of changed.slice(1)) {
 96	    // Context überlappt nur, wenn zwischen den Änderungen höchstens 2*context Zeilen liegen.
 97	    if (index - last <= contextLines * 2 + 1) {
 98	      last = index;
 99	    } else {
100	      ranges.push([Math.max(0, first - contextLines), Math.min(steps.length - 1, last + contextLines)]);
101	      first = index;
102	      last = index;
103	    }
104	  }
105	  ranges.push([Math.max(0, first - contextLines), Math.min(steps.length - 1, last + contextLines)]);
106	
107	  return ranges.map(([start, end]) => {
108	    const selected = steps.slice(start, end + 1);

